ALTER TABLE public.studio_templates ADD COLUMN template_number integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1000);
CREATE UNIQUE INDEX studio_templates_template_number_key ON public.studio_templates (template_number);
GRANT USAGE, SELECT ON SEQUENCE public.studio_templates_template_number_seq TO service_role;
COMMENT ON COLUMN public.studio_templates.template_number IS 'Stable internal catalogue number, independent of the user-facing creative title and existing slug.';